import{R as t,e as r,f as o,U as n}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"CleverReach","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/email-marketing/cleverreach.md","filePath":"integrations/email-marketing/cleverreach.md","lastUpdated":1775908585000}'),a={name:"integrations/email-marketing/cleverreach.md"};function i(l,e,s,c,h,g){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="cleverreach" tabindex="-1">CleverReach <a class="header-anchor" href="#cleverreach" aria-label="Permalink to &quot;CleverReach&quot;">​</a></h1><p>Follow the below steps to connect to the CleverReach API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Email Marketing</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select CleverReach as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-cleverreach-api" tabindex="-1">Step 2. Connect to the CleverReach API <a class="header-anchor" href="#step-2-connect-to-the-cleverreach-api" aria-label="Permalink to &quot;Step 2. Connect to the CleverReach API&quot;">​</a></h3><ol><li>Go to <a href="https://cleverreach.com/" target="_blank">CleverReach</a>, and login to your account.</li><li>Click on your profile dropdown on the top-right of the screen, and select <strong>My Account</strong>.</li><li>Click <strong>Interfaces</strong> → <strong>REST API</strong>.</li><li>Click the <strong>Create OAuth2 App</strong> button.</li><li>In the <strong>Redirect URL</strong> field, enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>Copy the <strong>Client ID</strong> from CleverReach and paste in the <strong>Client ID</strong> field in Formie.</li><li>Copy the <strong>Client Secret</strong> from CleverReach and paste in the <strong>Client Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to CleverReach, where you must approve Formie to access your CleverReach account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const m=t(a,[["render",i]]);export{p as __pageData,m as default};
